'use strict';
// Independent delayed-snapshot model: commits happen in request order, while
// delivery never writes persisted. This distinguishes stale UI from storage loss.
window.commitSnapshots=()=>{for(const c of calls){if(c.snapshot)continue;let next=clone(persisted);if(c.name==='setTheme')next.themeId=c.arg;if(c.name==='saveCustomTheme'){next.themeId='custom';next.customTheme={...next.customTheme,...c.arg}}if(c.name==='setUiPreferences')Object.assign(next,c.arg);persisted=next;c.snapshot=clone(next);trace.push({seq:trace.length,epoch,type:'synthetic-commit',name:c.name,arg:c.arg,state:clone(next)})}};
window.deliverSnapshot=(index,fail=false)=>{const c=calls[index];if(c.settled)throw Error('duplicate delivery');c.settled=true;trace.push({seq:trace.length,epoch,type:'snapshot-delivery',index,name:c.name,fail,persisted:clone(persisted)});if(fail)c.reject(Error('synthetic settings write failure'));else c.resolve(clone(c.snapshot));};
window.runFixChecks=async()=>{
 const checks=[];const check=(name,observed,expected,details)=>checks.push({name,observed,expected,...(details===undefined?{}:{details})});
 const feedback=()=>Array.from(modal().querySelectorAll('[role="status"],[role="alert"]')).filter(e=>e.getClientRects().length).map(e=>e.textContent).join('|');
 await reset();click('#skinApplyCustom');click('#skinApplyCustom');await tick();check('custom same tick click issues one request and exposes busy',{requests:calls.length,disabled:$('#skinApplyCustom').disabled,busy:$('#skinApplyCustom').getAttribute('aria-busy'),status:/正在保存/.test(feedback())},{requests:1,disabled:true,busy:'true',status:true});
 for(let i=0;i<calls.length;i++)reply(i,true);await tick();check('custom rejection restores control and visible feedback without unhandled rejection',{disabled:$('#skinApplyCustom').disabled,busy:$('#skinApplyCustom').getAttribute('aria-busy'),error:/失败/.test(feedback()),unhandled:errors.length,open:opened()},{disabled:false,busy:null,error:true,unhandled:0,open:true});
 click('#skinApplyCustom');await tick();reply(calls.length-1);await tick();check('custom retry commits after rejected request',{open:opened(),theme:audit.snapshot().themeId,disabled:$('#skinApplyCustom').disabled},{open:false,theme:'custom',disabled:false});
 await reset();for(let i=0;i<5;i++)key('[data-skin-id="deep-ocean"]','Enter');await tick();check('five repeated theme activations while pending deduplicate',{requests:calls.length,busy:$('[data-skin-id="deep-ocean"]').getAttribute('aria-busy')},{requests:1,busy:'true'});for(let i=0;i<calls.length;i++)reply(i,true);await tick();check('theme failure has visible status and remains retryable',{error:/失败/.test(feedback()),open:opened(),busy:$('[data-skin-id="deep-ocean"]').getAttribute('aria-busy')},{error:true,open:true,busy:null});
 await reset();persisted.extraSyntheticField={retained:'future-host-field'};key('[data-skin-id="deep-ocean"]','Enter');key('[data-skin-id="porcelain-mist"]','Enter');await tick();commitSnapshots();deliverSnapshot(1);await tick();const beforeOld={theme:audit.snapshot().themeId,persisted:persisted.themeId};deliverSnapshot(0);await tick();check('latest persisted B stays B when only old A snapshot delivery is delayed',{beforeOld,after:audit.snapshot().themeId,persisted:persisted.themeId,extra:audit.snapshot().extraSyntheticField},{beforeOld:{theme:'porcelain-mist',persisted:'porcelain-mist'},after:'porcelain-mist',persisted:'porcelain-mist',extra:{retained:'future-host-field'}});
 await reset();click('#skinWallpaperTab');await tick();input('#skinWallpaperBrightness',100);input('#skinWallpaperBrightness',100,'change');input('#skinWallpaperBlur',8);input('#skinWallpaperBlur',8,'change');await tick();commitSnapshots();deliverSnapshot(1);await tick();deliverSnapshot(0);await tick();check('fixed latest persisted custom fields survive reversed snapshot delivery',{brightness:Number($('#skinWallpaperBrightness').value),blur:Number($('#skinWallpaperBlur').value),storedBrightness:persisted.customTheme.wallpaperBrightness,storedBlur:persisted.customTheme.wallpaperBlur},{brightness:100,blur:8,storedBrightness:100,storedBlur:8});
 await reset();input('#skinCustomAccent','#aabbcc');click('#skinApplyCustom');await tick();key('[data-skin-id="deep-ocean"]','Enter');await tick();commitSnapshots();deliverSnapshot(1);await tick();deliverSnapshot(0);await tick();check('later theme snapshot preserves prior normalized custom fields',{theme:audit.snapshot().themeId,accent:audit.snapshot().customTheme.accent,storedAccent:persisted.customTheme.accent},{theme:'deep-ocean',accent:'#aabbcc',storedAccent:'#aabbcc'});
 await reset();key('[data-skin-id="deep-ocean"]','Enter');key('[data-skin-id="porcelain-mist"]','Enter');await tick();calls[0].snapshot={...base(),themeId:'deep-ocean'};persisted=clone(calls[0].snapshot);deliverSnapshot(0);await tick();deliverSnapshot(1,true);await tick();check('newest failed save does not lose preceding successful committed state',{theme:audit.snapshot().themeId,persisted:persisted.themeId,error:/失败/.test(feedback()),open:opened()},{theme:'deep-ocean',persisted:'deep-ocean',error:true,open:true});
 await reset();key('[data-skin-id="deep-ocean"]','Enter');key('[data-skin-id="porcelain-mist"]','Enter');await tick();calls[1].snapshot={...base(),themeId:'porcelain-mist'};persisted=clone(calls[1].snapshot);deliverSnapshot(1);await tick();click('#skinQuickButton');await tick();const before=feedback();deliverSnapshot(0,true);await tick();check('old failure cannot replace new success or reopened feedback',{theme:audit.snapshot().themeId,feedback:feedback(),open:opened()},{theme:'porcelain-mist',feedback:before,open:true});
 await reset();click('#skinWallpaperTab');await tick();input('#skinWallpaperBrightness',100);input('#skinWallpaperBrightness',100,'change');await tick();commitSnapshots();input('#skinWallpaperBlur',12);await tick();deliverSnapshot(0);await tick();check('in-flight save response preserves a newer unsaved range preview',{blur:Number($('#skinWallpaperBlur').value),stateBlur:audit.snapshot().customTheme.wallpaperBlur,storedBlur:persisted.customTheme.wallpaperBlur},{blur:12,stateBlur:12,storedBlur:2});input('#skinWallpaperBlur',12,'change');await tick();commitSnapshots();deliverSnapshot(1);await tick();check('subsequent range change persists preserved draft alongside prior field',{brightness:persisted.customTheme.wallpaperBrightness,blur:persisted.customTheme.wallpaperBlur},{brightness:100,blur:12});
 await reset();click('#restoreOfficialTheme');await tick();if(calls.length===1&&calls[0].name==='setTheme'){reply(0);await tick()}check('restore official appearance uses single synchronous appearance patch',calls.map(x=>({name:x.name,arg:x.arg})),[{name:'setUiPreferences',arg:{themeId:'official',uiMode:'official',reducedMotion:false,lowPerformance:false}}]);for(let i=0;i<calls.length;i++)if(!calls[i].settled)reply(i);await tick();check('restore success closes and restores button',{theme:audit.snapshot().themeId,mode:audit.snapshot().uiMode,disabled:$('#restoreOfficialTheme').disabled,open:opened()},{theme:'official',mode:'official',disabled:false,open:false});
 await reset();click('#skinWallpaperTab');await tick();for(let i=1;i<=20;i++){input('#skinWallpaperBlur',i%13);input('#skinWallpaperBlur',i%13,'change')}await tick();commitSnapshots();for(let i=calls.length-1;i>=0;i--){deliverSnapshot(i);await tick()}check('burst latest range snapshot converges with committed storage and no busy leak',{blur:Number($('#skinWallpaperBlur').value),stored:persisted.customTheme.wallpaperBlur,unsettled:calls.filter(x=>!x.settled).length,busy:$('#skinApplyWallpaperAppearance').getAttribute('aria-busy')},{blur:7,stored:7,unsettled:0,busy:null});
 return checks;
};
